-- Records the real autonomy decision layer (decideAutonomyLevel) and its
-- check_autonomy_decision advisory tool. Applied live via Supabase MCP on
-- 2026-09-02; this file makes that reproducible from a fresh database.
insert into public.capability_registry
  (capability_key, name, description, category, skill, agent_tool_name, package_or_module, department, connection, required_permission, read_write, tenant_scope, cost_profile, risk, verification_method, status, status_notes, external_blocker, last_verified_at, last_verified_by)
values
  ('capability:autonomy_decision_layer', 'Real autonomy decision layer (decideAutonomyLevel) + check_autonomy_decision advisory tool', 'The real, deterministic autonomy decision layer named in the master brief''s Autonomy section: packages/workforce-core/src/autonomy/decision.ts''s decideAutonomyLevel produces one of four real intervention levels (AUTO, LOW_RISK_APPROVAL, OWNER_APPROVAL, BLOCKED) from real risk/confidence/reversibility/cost factors -- never a prompt-only concept, and fail-closed by construction (any missing/ambiguous safety-relevant input lands at OWNER_APPROVAL or BLOCKED, never AUTO; AUTO is reached only when every gate is explicitly satisfied). Deliberately separate from and composes with resolveCapabilityReadiness (capabilities/readiness.ts, pre-existing): readiness answers "CAN this run right now" (entitlements/integrations/kill-switch/static approvalRequired); this module answers "SHOULD this run without a human", a genuinely different question. Exposed as a new read-only agent tool, check_autonomy_decision (lib/agent-core/autonomy-decision-tool.ts), which consults a real capability from the static workforce registry (getCapability/listCapabilities, the same registry check_workforce_registry already reads) for its real riskLevel/approvalRequired/externalMutation, combined with the caller''s stated confidence/reversibility/cost for one specific proposed action. This tool is a policy CONSULT, not a live per-tenant readiness check (it does not resolve entitlements/integrations/kill-switch for a specific tenant -- check_capabilities already does that). Purely advisory: does not execute anything, does not bypass the real CONFIRM flow (control-handlers.ts), and does not itself flip any kill-switch or activate live autonomous execution -- "do not silently activate unsafe production autonomy" from the master brief is respected by construction, not just by policy.', 'ecosystem', null, 'check_autonomy_decision', 'packages/workforce-core/src/autonomy/decision.ts, lib/agent-core/autonomy-decision-tool.ts', 'Engineering', null, 'agent:read:capabilities', 'read', 'global', 'free', 'read', 'autonomy-decision.test.ts (new, 13 real assertions incl. every reason code and the fail-closed guarantee), wired into test:workforce-core (full suite passes), full-repo tsc --noEmit clean, lint clean, real NODE_ENV=production next build exit 0', 'REAL_EXPOSED', 'The decision function and its advisory tool are genuinely live and callable via WhatsApp/Admin/Client Copilot today. Wiring an AUTO-level decision to actually skip human confirmation in a live channel is a separate, deliberate future product decision this module does not make on its own -- intentionally left un-wired, not an oversight.', null, now(), 'claude_session_2026-09-02')
on conflict (capability_key) do nothing;
